<?php
declare(strict_types=1);
ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';
function pm_json(int $code,array $data):never{http_response_code($code);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
function pm_audit(PDO $db,int $uid,string $action,int $id,array $detail):void{$q=$db->prepare("INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,'parent_message',?,?)");$q->execute([$uid,$action,$id,json_encode($detail,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE)]);}
if(!signed_in())pm_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))pm_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);
$db=db();$uid=(int)$_SESSION['user_id'];$role=(string)$_SESSION['role'];if(!in_array($role,['parent','teacher'],true))pm_json(403,['ok'=>false,'message'=>'Parent–teacher messaging is available to linked parents and assigned teachers.']);
function pm_authorized(PDO $db,array $thread,int $uid,string $role):bool{
 if($role==='parent'){$q=$db->prepare("SELECT 1 FROM pupil_guardians g JOIN pupils p ON p.id=g.pupil_id AND p.school_id=g.school_id WHERE g.school_id=? AND g.pupil_id=? AND g.guardian_user_id=? AND p.status='active'");$q->execute([$thread['school_id'],$thread['pupil_id'],$uid]);return (int)$thread['guardian_user_id']===$uid&&(bool)$q->fetchColumn();}
 if((int)$thread['staff_user_id']!==$uid)return false;$q=$db->prepare("SELECT 1 FROM teacher_assignments a JOIN pupils p ON p.school_id=a.school_id AND p.class_level=a.class_level JOIN users u ON u.id=a.user_id AND u.role='teacher' AND u.status='active' JOIN school_memberships m ON m.user_id=a.user_id AND m.school_id=a.school_id WHERE a.user_id=? AND a.school_id=? AND a.active=1 AND p.id=? AND p.status='active' LIMIT 1");$q->execute([$uid,$thread['school_id'],$thread['pupil_id']]);return(bool)$q->fetchColumn();
}
try{
 if($_SERVER['REQUEST_METHOD']==='GET'){$view=(string)($_GET['view']??'threads');
  if($view==='recipients'&&$role==='parent'){$q=$db->prepare("SELECT p.id pupil_id,p.school_id,p.first_name,p.middle_name,p.last_name,p.class_level,s.name school_name FROM pupil_guardians g JOIN pupils p ON p.id=g.pupil_id AND p.school_id=g.school_id JOIN schools s ON s.id=p.school_id WHERE g.guardian_user_id=? AND p.status='active' ORDER BY s.name,p.last_name,p.first_name");$q->execute([$uid]);$children=$q->fetchAll();foreach($children as &$child){$q=$db->prepare("SELECT DISTINCT u.id user_id,u.name FROM teacher_assignments a JOIN users u ON u.id=a.user_id AND u.role='teacher' AND u.status='active' JOIN school_memberships m ON m.user_id=u.id AND m.school_id=a.school_id WHERE a.school_id=? AND a.class_level=? AND a.active=1 ORDER BY u.name");$q->execute([$child['school_id'],$child['class_level']]);$child['teachers']=$q->fetchAll();}unset($child);pm_json(200,['ok'=>true,'data'=>$children]);}
  if($view==='recipients'&&$role==='teacher'){$q=$db->prepare("SELECT DISTINCT p.id pupil_id,p.school_id,p.first_name,p.middle_name,p.last_name,p.class_level,s.name school_name,g.guardian_user_id user_id,u.name guardian_name FROM teacher_assignments a JOIN pupils p ON p.school_id=a.school_id AND p.class_level=a.class_level AND p.status='active' JOIN schools s ON s.id=p.school_id JOIN pupil_guardians g ON g.pupil_id=p.id AND g.school_id=p.school_id JOIN users u ON u.id=g.guardian_user_id AND u.status='active' AND u.role='parent' JOIN school_memberships m ON m.user_id=a.user_id AND m.school_id=a.school_id WHERE a.user_id=? AND a.active=1 ORDER BY s.name,p.last_name,p.first_name,u.name");$q->execute([$uid]);pm_json(200,['ok'=>true,'data'=>$q->fetchAll()]);}
  if($view==='messages'){$id=filter_var($_GET['thread_id']??null,FILTER_VALIDATE_INT);if(!$id)pm_json(422,['ok'=>false,'message'=>'Choose a conversation.']);$q=$db->prepare('SELECT c.*,p.first_name,p.middle_name,p.last_name,p.class_level,g.name guardian_name,t.name teacher_name FROM parent_conversations c JOIN pupils p ON p.id=c.pupil_id AND p.school_id=c.school_id JOIN users g ON g.id=c.guardian_user_id JOIN users t ON t.id=c.staff_user_id WHERE c.id=?');$q->execute([$id]);$thread=$q->fetch();if(!$thread||!pm_authorized($db,$thread,$uid,$role))pm_json(404,['ok'=>false,'message'=>'Conversation not found or no longer accessible.']);$db->prepare('UPDATE parent_messages SET read_at=CURRENT_TIMESTAMP WHERE conversation_id=? AND school_id=? AND sender_user_id<>? AND read_at IS NULL')->execute([$id,$thread['school_id'],$uid]);$q=$db->prepare('SELECT m.id,m.sender_user_id,m.message_body,m.created_at,m.read_at,u.name sender_name FROM parent_messages m JOIN users u ON u.id=m.sender_user_id WHERE m.conversation_id=? AND m.school_id=? ORDER BY m.created_at,m.id LIMIT 300');$q->execute([$id,$thread['school_id']]);pm_json(200,['ok'=>true,'data'=>['thread'=>$thread,'messages'=>$q->fetchAll()]]);}
  $sql="SELECT c.id thread_id,c.school_id,c.pupil_id,c.guardian_user_id,c.staff_user_id,c.status,c.updated_at,p.first_name,p.middle_name,p.last_name,p.class_level,IF(c.guardian_user_id=?,t.name,g.name) other_name,(SELECT m.message_body FROM parent_messages m WHERE m.conversation_id=c.id ORDER BY m.id DESC LIMIT 1) last_message,(SELECT COUNT(*) FROM parent_messages m WHERE m.conversation_id=c.id AND m.sender_user_id<>? AND m.read_at IS NULL) unread_count FROM parent_conversations c JOIN pupils p ON p.id=c.pupil_id AND p.school_id=c.school_id JOIN users g ON g.id=c.guardian_user_id JOIN users t ON t.id=c.staff_user_id WHERE ".($role==='parent'?'c.guardian_user_id=?':'c.staff_user_id=?')." ORDER BY c.updated_at DESC LIMIT 100";$q=$db->prepare($sql);$q->execute([$uid,$uid,$uid]);$rows=[];foreach($q->fetchAll() as $row){if(pm_authorized($db,$row,$uid,$role))$rows[]=$row;}pm_json(200,['ok'=>true,'data'=>$rows]);
 }
 if($_SERVER['REQUEST_METHOD']!=='POST')pm_json(405,['ok'=>false,'message'=>'Method not allowed.']);if(!hash_equals($_SESSION['csrf']??'',(string)($_SERVER['HTTP_X_CSRF_TOKEN']??$_POST['csrf']??'')))pm_json(400,['ok'=>false,'message'=>'Your session expired. Refresh and try again.']);$action=(string)($_POST['action']??'');
 if($action==='start'){$pupil=(int)($_POST['pupil_id']??0);$other=(int)($_POST['other_user_id']??0);if(!$pupil||!$other||$other===$uid)throw new DomainException('Choose a child and an authorized school contact.');$db->beginTransaction();$q=$db->prepare("SELECT p.school_id,p.class_level FROM pupils p JOIN pupil_guardians g ON g.pupil_id=p.id AND g.school_id=p.school_id WHERE p.id=? AND p.status='active' AND g.guardian_user_id=?");if($role==='parent')$q->execute([$pupil,$uid]);else{$q=$db->prepare("SELECT p.school_id,p.class_level FROM pupils p JOIN pupil_guardians g ON g.pupil_id=p.id AND g.school_id=p.school_id WHERE p.id=? AND p.status='active' AND g.guardian_user_id=?");$q->execute([$pupil,$other]);}$child=$q->fetch();if(!$child)throw new DomainException('That active pupil is not linked to the selected guardian.');$school=(int)$child['school_id'];$guardian=$role==='parent'?$uid:$other;$staff=$role==='teacher'?$uid:$other;
  $q=$db->prepare("SELECT 1 FROM teacher_assignments a JOIN users u ON u.id=a.user_id AND u.role='teacher' AND u.status='active' JOIN school_memberships m ON m.user_id=a.user_id AND m.school_id=a.school_id WHERE a.user_id=? AND a.school_id=? AND a.class_level=? AND a.active=1 LIMIT 1");$q->execute([$staff,$school,$child['class_level']]);if(!$q->fetchColumn())throw new DomainException('Choose a teacher currently assigned to this pupil’s class.');$q=$db->prepare('INSERT IGNORE INTO parent_conversations(school_id,pupil_id,guardian_user_id,staff_user_id) VALUES(?,?,?,?)');$q->execute([$school,$pupil,$guardian,$staff]);$created=$q->rowCount()===1;$q=$db->prepare('SELECT id,status FROM parent_conversations WHERE school_id=? AND pupil_id=? AND guardian_user_id=? AND staff_user_id=? FOR UPDATE');$q->execute([$school,$pupil,$guardian,$staff]);$thread=$q->fetch();if(!$thread||$thread['status']!=='open')throw new DomainException('This conversation is closed.');if($created)pm_audit($db,$uid,'create_conversation',(int)$thread['id'],['school_id'=>$school,'pupil_id'=>$pupil,'guardian_user_id'=>$guardian,'staff_user_id'=>$staff]);$db->commit();pm_json(200,['ok'=>true,'message'=>'Conversation opened.','data'=>['thread_id'=>(int)$thread['id']]]);}
 if($action==='send'){$id=(int)($_POST['thread_id']??0);$body=trim((string)($_POST['message']??''));$requestId=strtolower(trim((string)($_POST['client_request_id']??'')));if(!$id||$body===''||mb_strlen($body)>5000||!preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/',$requestId))throw new DomainException('Enter a message up to 5,000 characters and retry with a valid request key.');$db->beginTransaction();$q=$db->prepare('SELECT * FROM parent_conversations WHERE id=? FOR UPDATE');$q->execute([$id]);$thread=$q->fetch();if(!$thread||$thread['status']!=='open'||!pm_authorized($db,$thread,$uid,$role))throw new DomainException('This conversation is closed or no longer accessible.');$q=$db->prepare('INSERT IGNORE INTO parent_messages(conversation_id,school_id,sender_user_id,client_request_id,message_body) VALUES(?,?,?,?,?)');$q->execute([$id,$thread['school_id'],$uid,$requestId,$body]);$created=$q->rowCount()===1;$q=$db->prepare('SELECT id,conversation_id FROM parent_messages WHERE school_id=? AND sender_user_id=? AND client_request_id=?');$q->execute([$thread['school_id'],$uid,$requestId]);$saved=$q->fetch();$messageId=(int)($saved['id']??0);if(!$messageId||(int)$saved['conversation_id']!==$id)throw new DomainException('This retry key was already used for a different conversation. Start a new message submission.');if($created){$db->prepare('UPDATE parent_conversations SET last_message_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$id]);pm_audit($db,$uid,'send_message',$messageId,['school_id'=>(int)$thread['school_id'],'thread_id'=>$id,'pupil_id'=>(int)$thread['pupil_id']]);}$db->commit();pm_json(200,['ok'=>true,'message'=>$created?'Message sent.':'This message was already sent.','data'=>['thread_id'=>$id,'message_id'=>$messageId]]);}
 throw new DomainException('Choose a supported messaging action.');
}catch(DomainException $e){if($db->inTransaction())$db->rollBack();pm_json(422,['ok'=>false,'message'=>$e->getMessage()]);}catch(PDOException $e){if($db->inTransaction())$db->rollBack();error_log('Parent message DB error: '.$e->getMessage());pm_json(500,['ok'=>false,'message'=>'Messages could not be loaded or saved. Verify the messaging migration.']);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Parent messaging request failed: '.$e->getMessage());pm_json(500,['ok'=>false,'message'=>'The messaging request could not be completed.']);}
